/* eslint-disable @typescript-eslint/no-unused-expressions */

import CircularBuffer = require( './index' );


// TESTS //

// The function returns a circular buffer instance...
{
	new CircularBuffer( 3 ); // $ExpectType CircularBuffer<unknown>
	new CircularBuffer( [ 1, 2, 3 ] ); // $ExpectType CircularBuffer<number>
	new CircularBuffer( new Float64Array( 3 ) ); // $ExpectType CircularBuffer<number>
	new CircularBuffer( 'abc' ); // $ExpectType CircularBuffer<string>
	new CircularBuffer( { 'length': 10 } ); // $ExpectType CircularBuffer<unknown>
	new CircularBuffer<number>( 3 ); // $ExpectType CircularBuffer<number>
	new CircularBuffer<number>( [ 1, 2, 3 ] ); // $ExpectType CircularBuffer<number>
}

// The compiler throws an error if the constructor function is provided an invalid number of arguments...
{
	new CircularBuffer(); // $ExpectError
	new CircularBuffer( 3, 4 ); // $ExpectError
	new CircularBuffer( 3, 4, 5 ); // $ExpectError
}

// The compiler throws an error if the constructor function is provided a first argument which is not a number or an array-like object...
{
	new CircularBuffer( true ); // $ExpectError
	new CircularBuffer( false ); // $ExpectError
	new CircularBuffer( null ); // $ExpectError
	new CircularBuffer( undefined ); // $ExpectError
	new CircularBuffer( {} ); // $ExpectError
	new CircularBuffer( ( x: number ): number => x ); // $ExpectError
}

// The `clear` method returns a circular buffer instance...
{
	const b = new CircularBuffer<string>( 3 ); // $ExpectType CircularBuffer<string>

	b.clear(); // $ExpectType CircularBuffer<string>
}

// The compiler throws an error if the `clear` method is provided any arguments...
{
	const b = new CircularBuffer<string>( 3 );

	b.clear( 1 ); // $ExpectError
	b.clear( 1, 2 ); // $ExpectError
}

// The `count` property is a read-only number...
{
	const b = new CircularBuffer<string>( 3 );

	b.count; // $ExpectType number
}

// The compiler throws an error if attempting to set the read-only `count` property...
{
	const b = new CircularBuffer<string>( 3 );

	b.count = 1; // $ExpectError
	b.count += 1; // $ExpectError
}

// The `full` property is a read-only boolean...
{
	const b = new CircularBuffer<string>( 3 );

	b.full; // $ExpectType boolean
}

// The compiler throws an error if attempting to set the read-only `full` property...
{
	const b = new CircularBuffer<string>( 3 );

	b.full = true; // $ExpectError
	b.full = false; // $ExpectError
}

// The `iterator` method returns an iterator...
{
	const b = new CircularBuffer<string>( 3 ); // $ExpectType CircularBuffer<string>

	b.iterator(); // $ExpectType TypedIterableIterator<string>
	b.iterator( 1 ); // $ExpectType TypedIterableIterator<string>
	b.iterator( b.length ); // $ExpectType TypedIterableIterator<string>
}

// The returned iterator is iterable and iterates over values of the expected type...
{
	const b = new CircularBuffer<number>( 3 ); // $ExpectType CircularBuffer<number>
	const it = b.iterator( 2 ); // $ExpectType TypedIterableIterator<number>

	it.next(); // $ExpectType TypedIteratorResult<number>
	it.next().value; // $ExpectType number | undefined
	it.next().done; // $ExpectType boolean
	it[ Symbol.iterator ](); // $ExpectType TypedIterableIterator<number>
}

// The compiler throws an error if the `iterator` method is provided an argument which is not a number...
{
	const b = new CircularBuffer<string>( 3 );

	b.iterator( 'abc' ); // $ExpectError
	b.iterator( true ); // $ExpectError
	b.iterator( false ); // $ExpectError
	b.iterator( null ); // $ExpectError
	b.iterator( undefined ); // $ExpectError
	b.iterator( void 0 ); // $ExpectError
	b.iterator( [] ); // $ExpectError
	b.iterator( {} ); // $ExpectError
	b.iterator( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `iterator` method is provided an unsupported number of arguments...
{
	const b = new CircularBuffer<string>( 3 );

	b.iterator( 1, 2 ); // $ExpectError
	b.iterator( 1, 2, 3 ); // $ExpectError
}

// The `length` property is a read-only number...
{
	const b = new CircularBuffer<string>( 3 );

	b.length; // $ExpectType number
}

// The compiler throws an error if attempting to set the read-only `length` property...
{
	const b = new CircularBuffer<string>( 3 );

	b.length = 10; // $ExpectError
	b.length += 1; // $ExpectError
}

// The `push` method returns the removed element or `undefined`...
{
	const b = new CircularBuffer<string>( 3 ); // $ExpectType CircularBuffer<string>

	b.push( 'foo' ); // $ExpectType string | undefined
	b.push( 'bar' ); // $ExpectType string | undefined
	b.push( 'beep' ); // $ExpectType string | undefined
	b.push( 'boop' ); // $ExpectType string | undefined
}

// The compiler throws an error if the `push` method is provided an invalid argument...
{
	const b = new CircularBuffer<string>( 3 );

	b.push( 1 ); // $ExpectError
	b.push( true ); // $ExpectError
	b.push( false ); // $ExpectError
	b.push( null ); // $ExpectError
	b.push( undefined ); // $ExpectError
	b.push( [] ); // $ExpectError
	b.push( {} ); // $ExpectError
	b.push( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `push` method is provided an unsupported number of arguments...
{
	const b = new CircularBuffer<string>( 3 );

	b.push(); // $ExpectError
	b.push( 'foo', 'bar' ); // $ExpectError
}

// The `toArray` method returns an array of buffer values...
{
	const b = new CircularBuffer<string>( 3 ); // $ExpectType CircularBuffer<string>

	b.toArray(); // $ExpectType string[]
}

// The compiler throws an error if the `toArray` method is provided any arguments...
{
	const b = new CircularBuffer<string>( 3 );

	b.toArray( 1 ); // $ExpectError
	b.toArray( 1, 2 ); // $ExpectError
}

// The `toJSON` method returns a JSON-serialized circular buffer...
{
	const b = new CircularBuffer<string>( 3 ); // $ExpectType CircularBuffer<string>
	const o = b.toJSON(); // $ExpectType JSON<string>

	o.type; // $ExpectType "circular-buffer"
	o.length; // $ExpectType number
	o.data; // $ExpectType string[]
}

// The compiler throws an error if the `toJSON` method is provided any arguments...
{
	const b = new CircularBuffer<string>( 3 );

	b.toJSON( 1 ); // $ExpectError
	b.toJSON( 1, 2 ); // $ExpectError
}
